package com.chubb.apac.claims.modulith.assessment.service;import com.chubb.apac.claims.modulith.assessment.dto.request.*;import com.chubb.apac.claims.modulith.assessment.event.*;import com.chubb.apac.claims.modulith.assessment.mapper.AssessmentMapper;import com.chubb.apac.claims.modulith.assessment.model.*;import com.chubb.apac.claims.modulith.assessment.repository.*;import com.chubb.apac.claims.modulith.assessment.service.impl.AssessmentServiceImpl;import com.chubb.apac.claims.modulith.claim.api.*;import com.chubb.apac.claims.modulith.common.enums.*;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.context.ApplicationEventPublisher;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class AssessmentServiceImplTest{@Mock AssessmentRepository assessments;@Mock AssessmentStatusHistoryRepository history;@Mock DecisionRecordRepository decisions;@Mock ValidationRuleRepository rules;@Mock ClaimWorkflowApi claims;@Mock AssessmentIdGenerator ids;@Mock ApplicationEventPublisher events;AssessmentServiceImpl service;@BeforeEach void setup(){service=new AssessmentServiceImpl(assessments,history,decisions,rules,claims,new AssessmentMapper(),ids,events);}@Test void submitsAssessmentAndMovesClaim(){when(ids.nextAssessmentId()).thenReturn("ASM-1");when(assessments.saveAndFlush(any())).thenAnswer(x->x.getArgument(0));when(claims.requireAssignedStaffClaim("CLM-1","S1",Set.of(Market.SG))).thenReturn(new ClaimAccessView("CLM-1","U1",ClaimStatus.UNDER_REVIEW,Market.SG,ProductType.MOTOR,"S1"));var out=service.submit("CLM-1","S1",Set.of(Market.SG),"C1",new SubmitAssessmentRequest("Findings",RecommendedDecision.APPROVE,"Valid",new BigDecimal("100"),List.of()));assertThat(out.status()).isEqualTo(AssessmentStatus.SUBMITTED);verify(claims).transition("CLM-1",Set.of(Market.SG),ClaimStatus.UNDER_REVIEW,ClaimStatus.READY_FOR_DECISION,"Assessment submitted","S1","C1");verify(events).publishEvent(any(AssessmentSubmittedEvent.class));}}
